import{_ as e,H as n,f as a,i}from"./chunks/framework.CGh9YNlq.js";const P=JSON.parse('{"title":"Patterns:","description":"","frontmatter":{},"headers":[],"relativePath":"notes/DesignPatterns.md","filePath":"notes/DesignPatterns.md"}'),l={name:"notes/DesignPatterns.md"};function r(o,t,s,d,c,p){return n(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="patterns" tabindex="-1">Patterns: <a class="header-anchor" href="#patterns" aria-label="Permalink to &quot;Patterns:&quot;">​</a></h1><p>Controlling Content Style:</p><ul><li>Pattern 1: Logits Masking</li><li>Pattern 2: Grammar</li><li>Pattern 3: Style Transfer</li><li>Pattern 4: Reverse Neutralization</li><li>Pattern 5: Content Optimization</li></ul><p>Adding Knowledge: Bass</p><p><a href="./notes/BasicRAG" class="hero-link">* Pattern 6: Basic RAG</a></p><ul><li>Pattern 7: Semantic Indexing</li><li>Pattern 8: Indexing at Scale</li></ul><p>Adding Knowledge: Syncopation</p><ul><li>Pattern 9: Index-Aware Retrieval</li><li>Pattern 10: Node Postprocessing</li><li>Pattern 11: Trustworthy Generation</li><li>Pattern 12: Deep Search</li></ul><p>Extending Model Capabilities:</p><p><a href="./notes/CoT" class="hero-link">* Pattern 13: Chain of Thought</a></p><ul><li>Pattern 14: Tree of Thoughts(ToT)</li><li>Pattern 15: Adapter Tuning</li><li>Pattern 16: Evol-Instruct</li></ul><p>Improving Reliability:</p><ul><li>Pattern 17: LLM-as-Judge</li><li>Pattern 18: Reflection</li><li>Pattern 19: Dependency Injection</li><li>Pattern 20: Prompt Optimization</li></ul><p>Enabling Agents to Take Action:</p><ul><li>Pattern 21: Tool Calling</li><li>Pattern 22: Code Execution</li><li>Pattern 23: Multiagent Collaboration</li></ul><p>Addressing Constraints:</p><ul><li>Pattern 24: Small Language Model</li><li>Pattern 25: Prompt Caching</li><li>Pattern 26: Inference Optimization</li><li>Pattern 27: Degradation Testing</li><li>Pattern 28: Long-Term Memory</li></ul><p>Setting Safeguards:</p><ul><li>Pattern 29: Template Generation</li><li>Pattern 30: Assembled Reformat</li><li>Pattern 31: Self-Check</li><li>Pattern 32: Guardrails</li></ul><p>To let users train agents to do the tasks that form the workflow, the UX should allow users to complete the work without referencing any external system.(为了让用户训练智能体完成工作流中的任务，产品体验应该支持用户在系统内完成整个工作，而不需要参考任何外部系统，这里的外部系统可能是指：Excel,CRM,邮件系统，工单系统，数据库，网页后台，其他SaaS工具等) They can do this by using tools or APIs to bring any necessary data into the application. If a user has to go outside the application to hunt for information to enter, then the agent won&#39;t have the context it needs to recommend decisions, learn when recommendations are incorrect, and eventually learn to make decisions autonomously.</p><p>Each step of the workflow is executed by one or more agents, and each agent can be implemented independently of the others. These agents can follow a plan of action(with Chain of Thought[Pattern 13]), retrieve necessary data(with Basic RAG[Pattern 6] and Index-Aware Retrieval[Pattern 9]), and call tools as needed(with Tool Calling[Pattern 21]). In all this, they can recover from errors(with Reflection[Pattern 18]) and Self-Check[Pattern 31] or be implemented to trade off risk and creativity(with Template Generation[Pattern 29] and Assembled Reformat[Pattern 30]). It&#39;s important to choose an abstraction level and framework for each agent that lets you easily implement the patterns that are necessary for it.</p>',21)])])}const u=e(l,[["render",r]]);export{P as __pageData,u as default};
